import{_ as l,o as s,c as t,ah as a}from"./chunks/framework.ChH6X6u6.js";const b=JSON.parse('{"title":"Bulletins","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/admin/bulletins.md","filePath":"src/guide/admin/bulletins.md"}'),n={name:"guide/admin/bulletins.md"};function i(r,e,u,o,d,p){return s(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="bulletins" tabindex="-1">Bulletins <a class="header-anchor" href="#bulletins" aria-label="Permalink to &quot;Bulletins&quot;">​</a></h1><p>Cette page couvre la publication des bulletins côté administration — une fois que les enseignants ont saisi leurs notes et appréciations pour une période donnée (ce qui est leur propre travail, pas le vôtre), c&#39;est vous qui déclenchez la génération et la mise à disposition des bulletins.</p><h2 id="publier-les-bulletins-d-une-classe" tabindex="-1">Publier les bulletins d&#39;une classe <a class="header-anchor" href="#publier-les-bulletins-d-une-classe" aria-label="Permalink to &quot;Publier les bulletins d&#39;une classe&quot;">​</a></h2><p>Depuis <strong>Paramétrage scolaire → Classes</strong>, cliquez sur <strong>Bulletins</strong> sur la ligne de la classe concernée.</p><p>Pour publier :</p><ol><li>Choisissez la <strong>Période scolaire</strong> concernée dans le menu déroulant en haut de la page.</li><li>Cliquez sur <strong>Publier / republier les bulletins</strong>.</li></ol><p>Cela génère (ou régénère) le bulletin de chaque élève de la classe pour cette période, à partir des notes et appréciations déjà saisies.</p><p>À la <strong>première</strong> publication, les parents de chaque élève reçoivent un e-mail et une notification : c&#39;est par le bulletin qu&#39;ils apprennent les résultats de la période, pas note par note. Republier après une correction met à jour le bulletin déjà publié — les élèves et parents téléchargent toujours la dernière version — sans les prévenir une seconde fois.</p><p>Si aucune période scolaire n&#39;est configurée pour l&#39;année de cette classe, un message vous l&#39;indique — allez d&#39;abord créer une période dans <a href="/era-guide/guide/admin/structure-etablissement.html">Structure de l&#39;établissement</a>.</p><h2 id="suivre-et-telecharger-les-bulletins" tabindex="-1">Suivre et télécharger les bulletins <a class="header-anchor" href="#suivre-et-telecharger-les-bulletins" aria-label="Permalink to &quot;Suivre et télécharger les bulletins&quot;">​</a></h2><p>Le tableau sous le sélecteur de période liste chaque élève de la classe avec :</p><ul><li><strong>Statut</strong> — « Non publié », ou la date de publication du bulletin.</li><li>Un bouton de téléchargement (icône), disponible dès qu&#39;un bulletin a été généré pour cet élève.</li></ul><h2 id="modele-de-bulletin" tabindex="-1">Modèle de bulletin <a class="header-anchor" href="#modele-de-bulletin" aria-label="Permalink to &quot;Modèle de bulletin&quot;">​</a></h2><p>Le modèle visuel utilisé (Classique, Compact ou Traditionnel à la française) se choisit par classe, dans le formulaire de la classe — voir <a href="/era-guide/guide/admin/structure-etablissement.html#classes">Structure de l&#39;établissement</a>. Si aucun modèle n&#39;est choisi pour une classe, le modèle par défaut de l&#39;établissement s&#39;applique.</p><p>Quel que soit le modèle, les matières du bulletin suivent le paramétrage des <a href="/era-guide/guide/admin/structure-etablissement.html#matieres-par-departement">matières par département</a> :</p><ul><li>elles sont regroupées sous leur <strong>rubrique</strong> (« Tronc commun », « Sciences »…), dans l&#39;<strong>ordre</strong> indiqué ; les matières sans rubrique viennent sans intitulé ;</li><li>les <strong>spécialités</strong> forment un bloc à part, « Enseignements de spécialité » : d&#39;abord celles que l&#39;élève suit, puis celles qu&#39;il a abandonnées, marquées « (abandonnée) ».</li></ul><p>Le modèle <strong>Traditionnel</strong> ajoute une colonne par type d&#39;évaluation qui compte dans la moyenne (la moyenne de l&#39;élève en devoirs, en compositions…) et une colonne « Moy. × coef. ». Les types <a href="/era-guide/guide/admin/structure-etablissement.html#types-d-evaluation">hors moyenne</a> n&#39;y figurent pas.</p><p>Un bulletin déjà publié est un document figé : un changement de paramétrage n&#39;apparaît qu&#39;après avoir republié les bulletins de la classe.</p>',18)])])}const m=l(n,[["render",i]]);export{b as __pageData,m as default};
